[CmdletBinding()]
param([string]$BundlesDirectory='ES/Output/WebPageStudio/bundles')
$ErrorActionPreference='Stop';$OutputEncoding=[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false);$root=[IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')+'\';$dir=[IO.Path]::GetFullPath((Join-Path $root $BundlesDirectory));if(-not $dir.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw 'BundlesDirectory must remain under project root.'};$rows=[System.Collections.Generic.List[object]]::new();foreach($d in @(Get-ChildItem -LiteralPath $dir -Directory|Where-Object Name -notlike 'locale-bundle-refresh-*')){$req=Join-Path $d.FullName 'request-en.json';$manifest=Join-Path $d.FullName 'manifest.json';$reason=[System.Collections.Generic.List[string]]::new();if(-not(Test-Path $req -PathType Leaf)){$reason.Add('missing-request-en')};if(-not(Test-Path $manifest -PathType Leaf)){$reason.Add('missing-manifest')};$contracts=@(Get-ChildItem -LiteralPath $d.FullName -Recurse -Filter 'web-page-contract.json' -File);if($contracts.Count -eq 0){$reason.Add('missing-locale-contracts')};$rows.Add([pscustomobject]@{bundle=$d.Name;replayReady=($reason.Count -eq 0);reasons=@($reason);requestExists=(Test-Path $req -PathType Leaf);manifestExists=(Test-Path $manifest -PathType Leaf);contractCount=$contracts.Count})};$ready=@($rows|? replayReady).Count;$notReady=$rows.Count-$ready;[pscustomobject]@{schemaVersion=1;recordType='WebPageStudioBundleReplayReadinessReceipt';status=if($notReady -eq 0){'ready'}else{'partial'};bundleCount=$rows.Count;readyCount=$ready;notReadyCount=$notReady;bundles=$rows;evidenceLevel='S1';runtimeStatus='runtime-not-run';claimsNotProven=@('Readiness report does not rewrite artifacts or prove browser, backend, Unity, or production runtime behavior.') }|ConvertTo-Json -Depth 8
